/* CHEF D’ÉQUIPE INCENDIE — fichier 3 : Sauvetages et forcement
   Sources : Livret stagiaire Chef d’équipe incendie SDIS 51 (v2019.1), Partie 1 (§ 1.2) et Partie 3 (§ 3.1, p. 24) ;
   GTO Sauvetages et mises en sécurité (DGSCGC, V1.1, novembre 2020), chap. II, III, IV et V ;
   Fiches Halligan S+F « Forcement des accès » (SDIS 51, 11/08/2015 — porte pédagogique de forcement, PARTIE B formateur) ;
   GTO Établissements et techniques d’extinction (DGSCGC, 2018), fiche ETEX-STR-ETB-1 ; GTO Engagement en milieu vicié (DGSCGC, 2019) ;
   GDO Incendies de structures (DGSCGC, 2018).
   Le GNR LSPCC auquel renvoie le livret (§ 3.1) n’est pas fourni : les manœuvres sont traitées d’après le GTO Sauvetage. */
var CE3 = 'CE 3 — Sauvetages et forcement';
var LIVCE = 'Livret stagiaire Chef d’équipe incendie SDIS 51 (v2019.1)';
var GTOS = 'GTO Sauvetages et mises en sécurité (DGSCGC, V1.1, 2020)';
var HAL = 'Fiches Halligan S+F « Forcement des accès » (SDIS 51, 11/08/2015)';

/* =====================================================================================
   1. SAUVETAGES PAR L’EXTÉRIEUR AU LSPCC
   ===================================================================================== */
VSAV.chap({
  id: 'ce-sauvetage-ext', part: 'ce', seq: CE3,
  title: 'Le chef d’équipe dans les sauvetages : sauvetage par l’extérieur au LSPCC', short: 'Sauvetage par l’extérieur', motif: 'rope',
  status: 'partiel',
  todo: '<p>Le livret CE (§ 3.1, p. 24) renvoie au <b>GNR « Lot de sauvetage et de protection contre les chutes »</b> (DGSCGC, 1999), pour les manœuvres « Sauvetage d’une victime par l’extérieur – points fixes naturels » et « – point fixe humain ». Ce GNR <b>ne figure pas</b> dans les documents fournis. Les manœuvres sont présentées ici d’après le <b>GTO Sauvetages et mises en sécurité</b> (2020), qui décrit le sauvetage par l’extérieur avec un point fixe et avec l’équipier en point fixe, mais sans détailler séparément les ordres et le déroulé du GNR.</p>',
  sources: [LIVCE + ', Partie 1, § 1.2 (p. 8-12) et Partie 3, § 3.1 (p. 24)', GTOS + ', chap. III § 3.2 et 3.4 (p. 72-81), § 4 et 5 (p. 82-92)'],
  summary: 'Ce que le livret attend du chef d’équipe dans un sauvetage, puis la manœuvre de sauvetage par l’extérieur au LSPCC (point fixe ou équipier en point fixe) vue du chef : choix, contrôles, compte rendu.',
  why: '<b>Pourquoi le chef d’équipe est-il au cœur du sauvetage ?</b> C’est lui qui découvre la victime, lui qui choisit le point fixe et réalise l’amarrage, lui qui contrôle les mousquetons et régule la descente. Le livret lui donne une marge d’<b>initiative</b> que l’équipier n’a pas — et la responsabilité qui va avec : la sécurité de son équipier et un compte rendu immédiat à son chef d’agrès. Un mousqueton non vérifié ou un ancrage douteux, et c’est la victime, ou le binôme, qui chute.',
  sections: [
    { id: 'role', t: 'Le chef d’équipe face à un sauvetage', ic: 'team', src: LIVCE + ', Partie 1, § 1.2 « Principes du commandement opérationnel » (p. 8-9)',
      html: '<div class="callout ok"><b>Ce que dit le livret (« SAUVETAGE »)</b> : les sauvetages sont <b>ordonnés par le chef d’agrès</b>. Toutefois, le chef d’équipe doit faire preuve d’<b>initiative</b> si, à un quelconque moment de l’intervention, un sauvetage à faire se présente à lui. Il doit toujours avoir à l’esprit la <b>sécurité de son équipier</b> et <b>rendre compte immédiatement</b> d’une opération de sauvetage en cours ou terminée.</div>' +
        '<p>Si, pour un sauvetage, il doit traverser un appartement ou un local et que les occupants s’y opposent, le chef d’équipe a <b>le droit et le devoir de pénétrer malgré tout</b> dans le lieu considéré, <b>de force si nécessaire</b>.</p>' +
        '<div class="tw"><table><thead><tr><th>Situation</th><th>Ce que fait le chef d’équipe (livret)</th></tr></thead><tbody>' +
        '<tr><td>Reconnaissance, en cas de <b>péril</b></td><td>Droit de visiter appartements, caves, greniers, ateliers… à son initiative ; en cas de refus des occupants, il en <b>rend compte immédiatement</b>.</td></tr>' +
        '<tr><td>Reconnaissance <b>sans urgence</b></td><td>Demande impérativement au chef d’agrès l’assistance de la police ou de la gendarmerie et <b>attend leur arrivée</b> avant de pénétrer.</td></tr>' +
        '<tr><td><b>Sauvetage</b> et occupants opposés</td><td>Droit et devoir de pénétrer, de force si nécessaire.</td></tr>' +
        '<tr><td>Personne en <b>danger immédiat</b> ou binôme en difficulté pendant une autre mission</td><td>Seul ce critère d’<b>urgence absolue</b> l’autorise à détourner son binôme de la mission reçue.</td></tr>' +
        '</tbody></table></div>' +
        '<p>Le livret cite expressément les <b>règles d’emploi du LSPCC</b> parmi les règles de sécurité individuelle dont le chef d’équipe est « personnellement et directement responsable » au sein de son équipe.</p>' },
    { id: 'gnr', t: 'Ce que demande le livret (§ 3.1) et ce qui est disponible', ic: 'book', src: LIVCE + ', Partie 3, § 3.1 (p. 24) et bibliographie (p. 30)',
      html: '<p>Le livret consacre sa Partie 3 aux sauvetages au moyen du lot de sauvetage (le titre écrit « LSPP »). Il ne contient pas de cours : il demande de se procurer le <b>Guide national de référence (GNR) « Lot de sauvetage et de protection contre les chutes »</b>, principalement pour deux manœuvres :</p>' +
        '<ul class="check"><li>Sauvetage d’une victime par l’extérieur – <b>points fixes naturels</b> ;</li><li>Sauvetage d’une victime par l’extérieur – <b>point fixe humain</b>.</li></ul>' +
        '<div class="callout warn">Le GNR LSPCC (DGSCGC, 1999, cité en bibliographie) <b>n’est pas dans le dossier fourni</b>. Les sections suivantes s’appuient sur le <b>GTO Sauvetages et mises en sécurité</b> (2020), présent dans le dossier, qui décrit le « sauvetage par l’extérieur avec un point fixe » et « avec l’équipier en point fixe ». Le vocabulaire diffère : le GTO classe les ancrages en <b>naturels</b> (arbres, rochers), <b>structurels</b> (poutre, pilier, rambarde, colonne sèche, engin…) et <b>artificiels</b> (échelle à main, outil de forcement, étais…), et ne reprend pas l’expression « points fixes naturels » du GNR.</div>' +
        '<p class="small muted">Les bases du LSPCC (composition, facteur de chute, nœuds, syndrome du harnais, entretien) sont dans le chapitre équipier <a href="#/c/inc-lspcc">Les sauvetages au moyen du LSPCC</a> ; ce chapitre se concentre sur ce que <b>le chef</b> choisit, fait et contrôle.</p>' },
    { id: 'roles', t: 'Sauvetage par l’extérieur : qui fait quoi', ic: 'list', src: GTOS + ', chap. III § 3.4.2 (p. 78-79)',
      html: '<p>Le <b>chef d’agrès</b> désigne le personnel, indique le lieu de sauvetage et fixe les moyens d’accès. Dans le binôme 1, presque toutes les décisions techniques reviennent au <b>chef d’équipe</b> :</p>' +
        '<div class="tw"><table><thead><tr><th>Chef d’équipe (binôme 1)</th><th>Équipier (binôme 1)</th></tr></thead><tbody>' +
        '<tr><td>Se munit d’un lot de sauvetage ; se rend au lieu désigné.</td><td>Se munit d’une commande.</td></tr>' +
        '<tr><td>Va chercher la victime et l’approche de l’endroit choisi pour l’évacuer.</td><td>—</td></tr>' +
        '<tr><td><b>Choisit un ou deux points fixes</b> ; <b>réalise l’amarrage</b> ; installe le dispositif de descente <b>après avoir estimé la hauteur</b>.</td><td>Équipe la victime du triangle ou du harnais.</td></tr>' +
        '<tr><td>Relie le harnais ou le triangle de la victime à la corde avec le mousqueton ; <b>vérifie la fermeture de tous les mousquetons</b>.</td><td>Accroche la commande (qui sert à écarter la victime de la façade) à l’anneau dorsal ; envoie l’autre extrémité au binôme 2.</td></tr>' +
        '<tr><td>Veille au <b>contrôle du frein de charge</b> et aide au besoin à l’engagement de la victime dans la descente.</td><td>Engage la victime dans la descente.</td></tr>' +
        '<tr><td><b>Contrôle et régule la descente</b> de la victime.</td><td>—</td></tr>' +
        '</tbody></table></div>' +
        '<p><b>Binôme 2</b> : se munit du matériel sur ordre, écarte la victime de la façade (commande) puis la réceptionne.</p>',
      figs: [{ img: 'img/ce/3/ext-points-fixes.jpg', cap: 'Avec un point fixe (à gauche) et avec l’équipier en point fixe (à droite)', txt: '<p>À gauche, le dispositif est amarré à un ancrage ; à droite, l’équipier allongé, jambes contre le mur, sert lui-même de point fixe. Dans les deux cas, le binôme 2 au sol tient la commande pour écarter la victime de la façade.</p>', src: GTOS + ', p. 79' }] },
    { id: 'pointfixe', t: 'Choisir et réaliser le point fixe', ic: 'pin', src: GTOS + ', chap. III § 3.2.1 et 3.2.2 (p. 72-74)',
      html: '<p>Le choix du point fixe est une décision du chef d’équipe. Pour le GTO, la fiabilité d’un ancrage relève <b>du bon sens, de l’expérience et de la connaissance du terrain</b>.</p>' +
        '<ul class="check"><li>Quelle que soit la nature de l’ancrage, <b>en cas de doute, le multiplier</b>.</li>' +
        '<li>Plusieurs ancrages : <b>répartir l’effort</b> sur l’ensemble ; angle entre les 2 anneaux de sangle <b>≤ 90°</b>.</li>' +
        '<li>Amarrage d’évacuation rapide : <b>a minima un connecteur et un anneau cousu</b>.</li>' +
        '<li>La résistance d’un anneau dépend de son positionnement sur l’ancrage et est réduite par un nœud.</li>' +
        '<li>Le mousqueton ne doit <b>pas travailler en porte-à-faux</b> (traction de biais par rapport à son grand axe).</li>' +
        '<li>Véhicule en ancrage : moteur arrêté et clé retirée, vitesse engagée, frein de parc serré, roues calées.</li></ul>' +
        '<p>Avant d’installer le frein de charge, le chef <b>estime la hauteur</b> : le GTO rappelle qu’il peut parfois suffire de descendre la victime <b>de quelques mètres</b> pour la mettre en sécurité, et que <b>la technique la plus simple et la plus sécuritaire</b> est à rechercher.</p>' },
    { id: 'humain', t: 'L’équipier en point fixe (« point fixe humain »)', ic: 'hand', src: GTOS + ', chap. III § 3.2.1 (p. 73) et § 3.4.2 (p. 78)',
      html: '<p><b>Quand ?</b> En l’absence de point d’ancrage, ou lorsque l’urgence de la situation rend impossible l’installation de tout amarrage. Cette manœuvre est <b>garante de rapidité</b>.</p>' +
        '<ul class="check"><li>L’équipier, muni du <b>harnais équipé du descendeur</b>, est <b>allongé, les jambes à 90° contre le mur</b> ; il contrôle la descente.</li>' +
        '<li>Dans ce cas, le <b>chef d’agrès doit participer à la mise au vide</b> de la victime.</li>' +
        '<li>La hauteur entre le frein de charge et le point d’appui sur le passage dans le vide doit être <b>supérieure ou égale à 20 cm</b>.</li></ul>' +
        '<div class="callout warn">Le GTO ne détaille pas, pour cette variante, une répartition des rôles différente du tableau général : le déroulé précis et les ordres de la manœuvre « point fixe humain » figurent dans le GNR LSPCC, non fourni.</div>' +
        '<p>Sur une échelle à crochets, une victime invalide ou inconsciente est descendue au LSPCC : le GTO indique que la <b>technique du sauveteur en point fixe sera le plus souvent utilisée</b> ; une échelle à crochets 2 plans placée dans l’encadrement d’une porte peut servir de point fixe en alternative (§ 4.2.3).</p>' },
    { id: 'controles', t: 'Les contrôles de sécurité du chef', ic: 'check', src: GTOS + ', chap. III § 3.4 (p. 76) et § 3.1.3 (p. 70)',
      steps: ['Matériel en parc, jamais posé sur un sol jonché de débris ; ne pas marcher sur les textiles.', 'Mousquetons vissés, sens de vissage si possible vers le bas ; un mousqueton pour relier deux anneaux cousus entre eux.', 'Huit descendeur toujours utilisé en point fixe.', 'Mise au vide (phase critique) : frein de charge sécurisé, mou de corde anticipé (passage de balcon). Victime inconsciente portée si possible par 2 sauveteurs, pieds en avant, face vers le sol.', 'Charge en tension : vérifier avant de poursuivre — comportement des amarrages, agrès sous tension, zones de frottement.', 'Tester sur quelques centimètres le bon fonctionnement du frein de charge.', 'Contrôler et réguler la descente jusqu’à la réception par le binôme 2 ; ne pas laisser la victime suspendue inerte (syndrome du harnais).'], stepsTitle: 'Contrôles avant et pendant la descente (7)',
      after: '<p class="small muted">Le chef d’équipe applique ces règles et les <b>fait appliquer</b> à son équipier : c’est la « sécurité individuelle au sein de son équipe » dont le livret le rend responsable.</p>' },
    { id: 'echelles', t: 'Les autres sauvetages par l’extérieur : ce qui revient au chef', ic: 'mountain', src: GTOS + ', chap. III § 4.2, 4.3.1 et 5.2 (p. 84-92)',
      html: '<div class="tw"><table><thead><tr><th>Moyen</th><th>Points utiles au chef d’équipe</th></tr></thead><tbody>' +
        '<tr><td><b>Prolongement d’une échelle à coulisse par l’échelle à crochets</b></td><td>Au commandement du chef d’agrès, le <b>chef d’équipe se saisit de l’échelle à crochets</b> et l’équipier de l’échelle à coulisse. L’équipier dresse l’échelle à crochets et la transmet au chef, qui monte à la coulisse, crochète une jambe, dresse l’échelle à crochets, la croche puis réalise une <b>traction pour tester la solidité de l’ouvrage</b> avant l’ascension.</td></tr>' +
        '<tr><td><b>Échelle à crochets</b> — victime valide qui ne descend pas seule</td><td>Un sapeur-pompier monte, aborde et rassure la victime, l’aide à franchir le vide (« se coller » à l’échelle) ; le second maintient fermement l’échelle. Autant que possible, <b>une personne par plan</b>. Si la descente est impossible : recours au LSPCC.</td></tr>' +
        '<tr><td><b>Échelle à coulisse</b> — victime invalide ou inconsciente</td><td>Technique à <b>trois</b> sapeurs-pompiers (binôme près de la victime + un sur l’échelle ; un 4<sup>e</sup> peut aider à la réception) ou à <b>deux</b>. Attention au <b>passage au vide</b> et aux éléments qui gênent la descente sur le dos (parachutes, trait…). En itinéraire de secours, l’échelle est <b>maintenue, calée ou amarrée</b>.</td></tr>' +
        '</tbody></table></div>' },
    { id: 'cr', t: 'Rendre compte d’un sauvetage', ic: 'clip', src: LIVCE + ', Partie 1, § 1.2 et § 3 « Les comptes rendus en cours d’action » (p. 9 et 12)',
      html: '<p>Le compte rendu d’un sauvetage est <b>immédiat</b>, qu’il soit en cours ou terminé. La <b>découverte de victime</b> fait partie des cas où un compte rendu en cours d’action est impératif, comme les moyens insuffisants, la difficulté à remplir la mission ou l’accident.</p>' +
        '<div class="tw"><table><thead><tr><th>Trame (livret)</th><th>Exemple de contenu</th></tr></thead><tbody>' +
        '<tr><td><b>Je suis</b></td><td>où se trouve le binôme</td></tr><tr><td><b>Je vois</b></td><td>la victime, son état, la menace</td></tr><tr><td><b>Je fais</b></td><td>le moyen de sauvetage engagé</td></tr><tr><td><b>Je demande</b></td><td>les moyens qui manquent (lot de sauvetage, binôme 2…)</td></tr>' +
        '</tbody></table></div>' +
        '<p>Il doit être <b>clair</b> et <b>concis</b> (un seul objet par compte rendu) et <b>précis</b> (pas de détails superflus).</p>' +
        '<p class="small muted">La colonne « exemple » illustre la trame ; elle ne provient pas du livret.</p>' }
  ],
  key: ['Sauvetages ordonnés par le chef d’agrès, mais initiative du chef d’équipe si un sauvetage se présente.', 'Toujours : sécurité de l’équipier + compte rendu immédiat (en cours ou terminé).', 'Occupants opposés à un sauvetage : droit et devoir de pénétrer, de force si nécessaire.', 'Le chef d’équipe choisit 1 ou 2 points fixes, amarre, estime la hauteur, vérifie tous les mousquetons, contrôle et régule la descente.', 'Doute sur un ancrage : le multiplier ; angle entre anneaux ≤ 90°.', 'Équipier en point fixe : allongé, jambes à 90° contre le mur ; le chef d’agrès participe à la mise au vide ; frein ≥ 20 cm du point d’appui.', 'Charge en tension : vérifier amarrages et frottements, tester le frein sur quelques centimètres.', 'Le GNR LSPCC cité par le livret n’est pas fourni : manœuvres d’après le GTO 2020.'],
  traps: ['Attendre un ordre alors qu’une victime est sous ses yeux : le livret demande l’initiative.', 'Faire un sauvetage sans en rendre compte immédiatement.', 'Pénétrer de force dans un local sans urgence au lieu de demander la police ou la gendarmerie par le chef d’agrès.', 'Lancer la descente sans avoir testé le frein de charge une fois la victime en tension.', 'Oublier que, avec l’équipier en point fixe, le chef d’agrès doit participer à la mise au vide.'],
  quiz: [
    { q: 'Qui ordonne les sauvetages selon le livret CE ?', c: ['Le chef d’agrès, mais le chef d’équipe doit prendre l’initiative si un sauvetage se présente à lui', 'Uniquement le COS', 'Le chef d’équipe, toujours seul', 'Le premier sapeur-pompier qui voit la victime, sans compte rendu'], e: 'Livret CE § 1.2 : les sauvetages sont ordonnés par le chef d’agrès ; toutefois le chef d’équipe doit faire preuve d’initiative et rendre compte immédiatement.', s: 'role' },
    { q: 'Pour un sauvetage, les occupants refusent l’accès à l’appartement à traverser :', c: ['Le chef d’équipe a le droit et le devoir de pénétrer, de force si nécessaire', 'Il attend la police', 'Il renonce et cherche un autre itinéraire', 'Il demande l’accord écrit du propriétaire'], e: 'Livret CE § 1.2 « SAUVETAGE » : droit et devoir de pénétrer malgré tout, de force si nécessaire. Sans urgence (reconnaissance), il faut au contraire demander police ou gendarmerie et attendre.', s: 'role' },
    { q: 'Dans le sauvetage par l’extérieur, qui choisit les points fixes et réalise l’amarrage ?', c: ['Le chef d’équipe du binôme 1', 'L’équipier du binôme 1', 'Le binôme 2', 'Le conducteur'], e: 'GTO § 3.4.2 : le chef d’équipe choisit un ou deux points fixes, réalise l’amarrage et installe le dispositif après avoir estimé la hauteur.', s: 'roles' },
    { q: 'Que fait le chef d’équipe une fois le triangle ou le harnais relié à la corde ?', c: ['Il vérifie la fermeture de tous les mousquetons', 'Il envoie la commande au binôme 2', 'Il descend avec la victime', 'Il quitte le lieu pour rendre compte'], e: 'GTO § 3.4.2 : il relie le harnais ou le triangle à la corde puis vérifie la fermeture de tous les mousquetons ; c’est l’équipier qui envoie la commande.', s: 'roles' },
    { q: 'Quand utiliser l’équipier comme point fixe ?', c: ['En l’absence d’ancrage ou quand l’urgence empêche tout amarrage', 'Systématiquement, c’est plus rapide', 'Uniquement en excavation', 'Seulement si la victime est valide'], e: 'GTO § 3.2.1 et 3.4.2 : manœuvre spécifique, garante de rapidité, en l’absence de point d’ancrage ou si l’urgence rend tout amarrage impossible.', s: 'humain' },
    { q: 'Avec l’équipier en point fixe, qui doit participer à la mise au vide ?', c: ['Le chef d’agrès', 'Le binôme 2', 'La victime elle-même', 'Personne d’autre'], e: 'GTO § 3.4.2 : « Dans ce cas, le chef d’agrès doit participer à la mise au vide de la victime. »', s: 'humain' },
    { q: 'Une fois la victime en tension sur le dispositif, avant de poursuivre :', c: ['Vérifier amarrages, agrès et frottements, et tester le frein sur quelques centimètres', 'Lâcher la commande', 'Retirer la protection de corde', 'Descendre le plus vite possible pour limiter le syndrome du harnais'], e: 'GTO § 3.4 : observer amarrages, agrès sous tension, zones de frottement ; tester sur quelques centimètres le bon fonctionnement du frein de charge.', s: 'controles' },
    { q: 'En cas de doute sur la solidité d’un ancrage, le GTO demande :', c: ['De le multiplier', 'De faire un nœud sur l’anneau', 'De passer à l’équipier en point fixe obligatoirement', 'De renoncer au sauvetage'], e: 'GTO § 3.2.1 : « Quelle que soit la nature de l’ancrage, en cas de doute, celui-ci doit être multiplié. »', s: 'pointfixe' }
  ]
});

/* =====================================================================================
   2. MÉTHODES D’EXTRACTION
   ===================================================================================== */
VSAV.chap({
  id: 'ce-extraction', part: 'ce', seq: CE3,
  title: 'Méthodes d’extraction : sortir un sauveteur ou une victime en binôme', short: 'Méthodes d’extraction', motif: 'stretcher',
  status: 'partiel',
  todo: '<p>Le livret CE (§ 4.2 « Méthodes d’extraction », p. 27) indique <b>« En cours de réalisation »</b>. Ce chapitre présente les techniques d’extraction du <b>GTO Sauvetages et mises en sécurité</b> (chap. IV « Techniques de sauvetage du sauveteur ») en attendant le contenu SDIS 51.</p>',
  sources: [LIVCE + ', § 4.2 (p. 27) : « en cours de réalisation »', GTOS + ', chap. IV (p. 109-129) et chap. V (p. 131-132)', 'GTO Engagement en milieu vicié (DGSCGC, 2019), chap. III § 7'],
  summary: 'Choisir et commander une technique d’extraction : par un équipier seul, par un binôme de sauvetage, avec des tuyaux, en milieu confiné (Denver drill) ; puis l’après-sauvetage.',
  why: '<b>Pourquoi apprendre ces techniques au chef d’équipe ?</b> Le binôme de sauvetage est dirigé par un chef d’équipe : c’est lui qui choisit, dans le noir et sous ARI, la prise et la technique adaptées à l’endroit (couloir étroit, escalier, fenêtre, trou dans un plancher). Un sapeur-pompier équipé est lourd et encombrant ; les techniques du GTO, nées souvent d’accidents mortels, transforment l’ARI de la victime en harnais et coordonnent les efforts pour gagner des minutes.',
  sections: [
    { id: 'cadre', t: 'Le cadre : le sauvetage du sauveteur', ic: 'alert', src: GTOS + ', chap. IV § 1 (p. 109-110)',
      html: '<div class="callout warn">Le livret CE annonce un § 4.2 « Méthodes d’extraction » <b>en cours de réalisation</b> : le contenu ci-dessous provient du GTO national.</div>' +
        '<p>Le GTO liste les paramètres propres au sauvetage d’un sauveteur :</p>' +
        '<ul class="check"><li><b>Anticipation</b> : prévoir, dès que possible lors d’engagements dans un bâtiment, des <b>itinéraires de repli et/ou de secours</b>.</li>' +
        '<li><b>Gestion de l’affect</b> : sauver un collègue génère stress et empathie qui peuvent prendre le pas sur les procédures ; le COS en tient compte.</li>' +
        '<li><b>Une « victime particulière »</b> : ARI, tenue de feu, ceinturon, localisation… imposent des techniques spécifiques.</li>' +
        '<li><b>Remplacement des équipes</b> : relever tout ou partie du personnel engagé peut être envisagé (sidération possible), avec suivi psychologique.</li>' +
        '<li><b>Renfort « secours »</b> : il faut à la fois poursuivre l’intervention et déployer un dispositif dédié ; le CODIS peut engager immédiatement un renfort.</li></ul>' +
        '<p>Les <b>espaces d’attente sécurisés (EAS)</b> des ERP, prévus pour le public, peuvent aussi servir de refuge aux sapeurs-pompiers en situation dégradée.</p>' +
        '<p class="small muted">Abordage (retourner, stopper l’alarme, conscience, air, manomètre, assistance en air, packaging) et message NELAR : voir le chapitre équipier <a href="#/c/inc-ari-sauvegarde">Sauvegarde opérationnelle</a>.</p>' },
    { id: 'choix', t: 'Choisir la technique', ic: 'brain', src: GTOS + ', chap. IV § 1 à 5 (p. 110-129)',
      html: '<div class="tw"><table><thead><tr><th>Situation</th><th>Techniques proposées par le GTO</th></tr></thead><tbody>' +
        '<tr><td>L’équipier est seul avec son binôme en difficulté (sans assistance immédiate)</td><td>Traction au sol sans matériel (dossard, poignets, chevilles), avec sangle, dans un escalier avec sangle</td></tr>' +
        '<tr><td>Un <b>binôme de sauvetage</b> est engagé</td><td>Halligan, traction parallèle, « tirer-pousser », échelle à coulisse, escalier, matériel de transport</td></tr>' +
        '<tr><td>Position basse obligatoire (structure basse, plafond de fumées)</td><td>Traction parallèle, « tirer-pousser »</td></tr>' +
        '<tr><td>Couloir étroit donnant sur une fenêtre</td><td>« Denver drill »</td></tr>' +
        '<tr><td>Sapeur-pompier tombé par un trou dans un plancher</td><td>« Nance drill » (tuyau en eau)</td></tr>' +
        '<tr><td>Binôme menacé en étage avec un moyen hydraulique</td><td>Évacuation par l’extérieur le long du tuyau amarré</td></tr>' +
        '<tr><td>Long cheminement ou accidenté</td><td>Planche de sauvetage, brancard souple (ou barquette, brancard cuillère)</td></tr>' +
        '</tbody></table></div>' +
        '<p><b>Préparer le déplacement</b> (GTO § 2) :</p><ul class="check"><li><b>Changer de direction</b> : relever les jambes à 90° en saisissant les chevilles, saisir une bretelle dorsale de l’ARI et pivoter le tout à 180°.</li>' +
        '<li><b>Retirer le harnais de l’ARI</b> pour alléger, seulement si : plus d’air et assistance en air impossible ; passages étroits obligatoires ; extraction par un ouvrant donnant à l’air libre.</li></ul>' },
    { id: 'equipier', t: 'Par un équipier : traction au sol', ic: 'hand', src: GTOS + ', chap. IV § 3.2 et 3.3 (p. 115-120)',
      html: '<p>Après le packaging, l’équipier tracte son binôme par le <b>dossard de l’ARI</b>, ou à l’aide d’une <b>sangle</b> vers la sortie si cela facilite le contact avec le binôme demandé en renfort. <b>Choisir le côté de prise</b> qui évite de fermer le robinet.</p>' +
        '<p><b>Convertir le dossard d’ARI en harnais</b> : desserrer les bretelles et abaisser le dossard au maximum ; passer la jambe, genou plié, par-dessus son épaule ; détacher la sangle ventrale, l’attacher dans l’entrecuisse, puis resserrer toutes les sangles.</p>' +
        '<div class="tw"><table><thead><tr><th>Variante</th><th>Mise en œuvre</th></tr></thead><tbody>' +
        '<tr><td>Par les bretelles</td><td>À la tête, dans l’axe ; saisir les deux bretelles, asseoir l’équipier (ou engager une main dans une bretelle) ; se relever et tracter vers l’arrière avec le poids du corps.</td></tr>' +
        '<tr><td>Par les poignets</td><td>À la tête, dans l’axe ; saisir les deux poignets, se relever, tracter vers l’arrière.</td></tr>' +
        '<tr><td>Par les chevilles</td><td>Aux pieds, dans l’axe ; saisir les chevilles, se relever, un avant-bras dessus et un dessous, tracter vers l’arrière.</td></tr>' +
        '<tr><td>Avec une sangle</td><td>Asseoir l’équipier en restant accroupi derrière lui ; sangle au-dessus du dossard, extrémités sous ses propres aisselles ; boucle passée sous les bretelles dorsales, extrémités réunies par un mousqueton ; se relever et tracter.</td></tr>' +
        '<tr><td>Dans un escalier, avec sangle</td><td>Quand l’équipier est en danger immédiat, ne peut se mouvoir et qu’il faut changer d’étage : l’asseoir dos aux escaliers, en le tenant par le haut des bretelles ; évacuer en marche arrière ou avant en cherchant des appuis avec les mains. Montée comme descente.</td></tr>' +
        '</tbody></table></div>' +
        '<div class="callout ok">Maintenir fermement ses prises ; <b>travailler avec les cuisses</b> pour se relever et tracter ; adapter la technique à la situation et aux capacités de l’équipier.</div>' },
    { id: 'binome', t: 'Par un binôme de sauvetage', ic: 'team', src: GTOS + ', chap. IV § 5.1 à 5.5 et 5.7 (p. 122-129)',
      html: '<div class="tw"><table><thead><tr><th>Technique</th><th>Principe</th></tr></thead><tbody>' +
        '<tr><td><b>Hache / Halligan tool</b></td><td>Le manche est engagé dans les bretelles du dossard : traction avec un support rigide. Très efficace pour monter ou descendre un escalier.</td></tr>' +
        '<tr><td><b>Traction parallèle</b></td><td>Les deux sauveteurs se placent en parallèle au niveau de la tête ; chacun agrippe une bretelle (main gauche pour celui de gauche, main droite pour celui de droite).</td></tr>' +
        '<tr><td><b>« Tirer-pousser »</b></td><td>Le 1<sup>er</sup>, à la tête dans l’axe, glisse une main dans une bretelle et tire avec le poids du corps ; il annonce « <b>Prêt</b> ». Le 2<sup>e</sup>, à l’arrière, lève la jambe de la victime, épaule au creux du genou, et pousse sur la cuisse en annonçant « <b>Go</b> ».</td></tr>' +
        '<tr><td><b>Échelle à coulisse, pieds en avant</b></td><td>À <b>trois</b> sauveteurs, ARI de la victime retiré au préalable : les deux à l’intérieur posent la victime sur le bord de la fenêtre ; celui sur l’échelle prend les jambes sur ses épaules et descend en tenant les montants.</td></tr>' +
        '<tr><td><b>Échelle à coulisse, tête en avant</b></td><td>À <b>deux</b> : victime posée sur le bord de la fenêtre puis en travers sur l’échelle ; le sauveteur sur l’échelle passe une main sous l’aisselle, l’autre entre les cuisses, et contrôle la descente par les montants.</td></tr>' +
        '<tr><td><b>Escalier</b></td><td>Monter : un sauveteur aux bretelles supérieures de l’ARI, l’autre sous les genoux. Descendre : victime face au sol, chaque sauveteur saisit une bretelle supérieure. Escalier étroit : variante sur le profil gauche (l’un retient, l’autre guide).</td></tr>' +
        '<tr><td><b>Brancard souple</b></td><td>Victime roulée en PLS sur le brancard ; anneaux cousus rouges en tête d’alouette dans les anses ; mousqueton aux pieds ; traction par les anneaux, la victime reste en PLS.</td></tr>' +
        '</tbody></table></div>' +
        '<p>Dans la traction parallèle et le « tirer-pousser », l’<b>équipier restant</b> du binôme en danger peut aider à extraire la victime ou ouvrir la voie au binôme de sauvetage. Avec le matériel de transport, veiller à ce que sa mise en œuvre ne fasse <b>pas perdre de temps</b>.</p>' +
        '<div class="callout warn">Maintenir fermement ses prises en gardant l’équilibre ; gainer la sangle abdominale pour garder le dos droit ; <b>prudence</b> avec la hache ou le Halligan ; vérifier les obstacles dangereux (trous, matériaux coupants). Les techniques sur échelle ne se pratiquent en formation qu’avec un matériel de protection adapté (LSPCC par exemple).</div>',
      figs: [{ img: 'img/ce/3/tirer-pousser.jpg', cap: 'La technique du « tirer-pousser »', txt: '<p>Le premier sauveteur tire par une bretelle du dossard, le second pousse sous le genou : l’effort coordonné (« Prêt » / « Go ») permet de rester en position basse sous les fumées.</p>', src: GTOS + ', p. 124' }] },
    { id: 'denver', t: 'Milieu confiné : le « Denver drill »', ic: 'walk', src: GTOS + ', chap. IV § 5.6 (p. 126-127)',
      html: '<p>Origine : le 28 septembre 1992, à Denver, un pompier retrouvé inconscient dans un couloir de <b>70 cm</b> de large donnant sur une fenêtre de <b>40 cm</b> n’a pu être extrait qu’au bout de <b>55 minutes</b> : impossible de se placer de chaque côté pour le soulever.</p>',
      steps: ['Victime tête côté fenêtre. Le 1er sauveteur entre par la fenêtre, passe par-dessus la victime et se place face à la fenêtre ; il la met sur le dos, la prend par le harnais de l’ARI et l’assoit dos à la fenêtre en laissant de la place.', 'Le 2e sauveteur s’assoit dos au mur, bouteille sur le côté, pieds à plat (il retire une sangle dorsale de son ARI).', 'Le 1er place la victime entre les jambes du 2e et resserre les sangles dorsales du harnais de la victime ; le 2e place ses mains sur la bouteille de la victime.', 'Le 1er pose la victime sur les genoux du 2e, qui met la bouteille de la victime sur le côté ; le 1er met les jambes de la victime sur ses épaules.', 'Le 1er pousse vers l’avant, le 2e pousse vers le haut (mains en poing pour éviter de se blesser au poignet).', 'La victime est posée sur le rebord de fenêtre, tournée face vers le bas, et réceptionnée par un moyen aérien ou une échelle à coulisse.'], stepsTitle: 'Denver drill (6)',
      figs: [{ img: 'img/ce/3/denver-drill.jpg', cap: 'Les étapes du Denver drill', txt: '<p>Vues de dessus puis de face : la victime est assise, hissée sur les genoux du 2<sup>e</sup> sauveteur puis poussée vers le rebord de la fenêtre.</p>', src: GTOS + ', p. 127' }] },
    { id: 'tuyaux', t: 'Avec les tuyaux d’incendie', ic: 'drop', src: GTOS + ', chap. IV § 4 (p. 120-122)',
      html: '<div class="tw"><table><thead><tr><th>Technique</th><th>Principe et précautions</th></tr></thead><tbody>' +
        '<tr><td><b>Évacuation par l’extérieur</b></td><td>Binôme engagé avec un moyen hydraulique face à un danger imminent : le tuyau est <b>amarré au préalable</b>. Le sapeur-pompier descend mains croisées sur le tuyau au niveau de la tête, pieds croisés ; son équipier assure en haut, puis il assure à son tour depuis le sol. Tuyau vide : nœud simple en amont de l’amarrage ; ne pas attacher au niveau d’un raccord.</td></tr>' +
        '<tr><td><b>Remontée d’un équipier tombé dans une excavation</b></td><td><b>Dernier recours</b>, pour un équipier <b>conscient et valide</b> ; garde une protection hydraulique. Ganse de tuyau descendue jusqu’à lui ; il s’installe à cheval, bras côté lance ; le <b>chef du binôme, à la lance</b>, bloque le tuyau au niveau de la boucle avec ses pieds ; traction coordonnée. Une sangle avec nœud français peut améliorer la prise.</td></tr>' +
        '<tr><td><b>« Nance drill »</b></td><td>Né d’un accident (Columbus, 25 juillet 1987 : chute de 4 m dans un sous-sol). Tuyau <b>en eau sous pression</b> : sangle ventrale de l’ARI sous la cuisse, boucle du tuyau sous le robinet de l’ARI, sangle amarrée sur les deux brins en passant dans une bretelle, traction coordonnée sur chaque brin. Un sauveteur descend faire les amarrages ; <b>au moins 4 pompiers</b> pour la remontée.</td></tr>' +
        '</tbody></table></div>' +
        '<div class="callout bad">Ces techniques ne doivent être enseignées qu’<b>en présence d’un formateur désigné</b> et avec l’utilisation du <b>LSPCC</b>.</div>' },
    { id: 'apres', t: 'Après le sauvetage', ic: 'reset', src: GTOS + ', chap. V (p. 131-132)',
      html: '<ul class="check"><li><b>Personnel</b> : hydratation, hygiène, débriefing ou défusing, repos selon l’intensité et la durée (nombreux sauvetages).</li>' +
        '<li><b>Matériel</b> (sous protection adaptée) : nettoyer, vérifier l’état et l’intégrité, retirer tout matériel agressé chimiquement ou thermiquement ou déformé, <b>rendre compte</b> de tout mouvement ou indisponibilité, ranger aux emplacements d’origine.</li>' +
        '<li><b>Partager</b> : le PEX (partage d’expérience) rend compte succinctement des faits, difficultés et enseignements ; le RETEX (retour d’expérience), plus complet, fait progresser doctrines et techniques.</li></ul>' }
  ],
  key: ['Livret CE § 4.2 « Méthodes d’extraction » : en cours de réalisation — référence : GTO Sauvetage chap. IV.', 'Anticiper des itinéraires de repli et de secours dès l’engagement.', 'Retirer le harnais ARI seulement si : plus d’air sans assistance possible, passages étroits, sortie par un ouvrant à l’air libre.', 'Dossard d’ARI converti en harnais : sangle ventrale dans l’entrecuisse.', 'Traction : choisir le côté qui ne ferme pas le robinet ; travailler avec les cuisses.', '« Tirer-pousser » : « Prêt » (celui qui tire) / « Go » (celui qui pousse).', 'Échelle : pieds en avant à 3 (ARI retiré), tête en avant à 2.', 'Nance drill : tuyau en eau, au moins 4 pompiers ; techniques tuyaux enseignées avec formateur désigné et LSPCC.'],
  traps: ['Croire que le livret SDIS 51 fixe déjà les méthodes d’extraction : il est « en cours de réalisation ».', 'Tracter par le côté qui ferme le robinet de l’ARI.', 'Retirer l’ARI de la victime alors qu’il lui reste de l’air et qu’aucun passage étroit ne l’impose.', 'Perdre du temps à installer un brancard quand une traction suffit.', 'S’entraîner aux techniques sur tuyaux ou échelle sans LSPCC.'],
  quiz: [
    { q: 'Que contient le livret CE au § 4.2 « Méthodes d’extraction » ?', c: ['La mention « en cours de réalisation »', 'Le Denver drill détaillé', 'Un renvoi au GNR LSPCC', 'La liste des brancards du VSAV'], e: 'Livret CE p. 27 : « En cours de réalisation ». Le chapitre s’appuie sur le GTO Sauvetage chap. IV.', s: 'cadre' },
    { q: 'Dans quel cas le GTO envisage-t-il de retirer le harnais de l’ARI de la victime ?', c: ['Plus d’air et assistance impossible, passage étroit, ou sortie par un ouvrant à l’air libre', 'Systématiquement avant toute traction', 'Jamais', 'Uniquement si la victime est consciente'], e: 'GTO chap. IV § 2 : ces trois cas seulement.', s: 'choix' },
    { q: 'Pour convertir le dossard d’ARI en harnais, la sangle ventrale est :', c: ['Détachée puis attachée dans l’entrecuisse', 'Retirée', 'Passée autour du cou', 'Laissée en place sans modification'], e: 'GTO § 3.2.1 : détacher la sangle ventrale, l’attacher dans l’entrecuisse, resserrer toutes les sangles.', s: 'equipier' },
    { q: 'Dans le « tirer-pousser », qui annonce « Go » ?', c: ['Le sauveteur qui pousse, à l’arrière', 'Celui qui tire, à la tête', 'Le chef d’agrès', 'La victime'], e: 'GTO § 5.3 : celui qui tire dit « Prêt », celui qui pousse sur la cuisse dit « Go ».', s: 'binome' },
    { q: 'L’évacuation sur échelle à coulisse « pieds en avant » se fait :', c: ['À trois sauveteurs, ARI de la victime retiré', 'À deux sauveteurs, ARI conservé', 'Seul', 'À quatre, victime sur un brancard'], e: 'GTO § 5.4.1 : trois sauveteurs, ARI préalablement retiré ; la technique « tête en avant » se fait à deux.', s: 'binome' },
    { q: 'Le « Denver drill » répond à quelle configuration ?', c: ['Un couloir étroit donnant sur une petite fenêtre', 'Une chute dans un sous-sol par un trou', 'Une victime en excavation', 'Un escalier en colimaçon'], e: 'GTO § 5.6 : couloir de 70 cm donnant sur une fenêtre de 40 cm (Denver, 1992).', s: 'denver' },
    { q: 'Combien de pompiers au minimum pour la remontée en « Nance drill » ?', c: ['4', '2', '3', '6'], e: 'GTO § 4.3 : un minimum de 4 pompiers est nécessaire pour réaliser la remontée dans de bonnes conditions.', s: 'tuyaux' },
    { q: 'Les techniques de dégagement avec tuyaux ne s’enseignent :', c: ['Qu’en présence d’un formateur désigné et avec le LSPCC', 'Qu’en intervention réelle', 'Que sur mannequin sans protection', 'Qu’aux équipes SMPM'], e: 'GTO chap. IV § 4.2 (encadré).', s: 'tuyaux' }
  ]
});

/* =====================================================================================
   3. PORTE PÉDAGOGIQUE DE FORCEMENT
   ===================================================================================== */
VSAV.chap({
  id: 'ce-forcement', part: 'ce', seq: CE3,
  title: 'Diriger un forcement : la porte pédagogique', short: 'Diriger un forcement', motif: 'hand',
  sources: [HAL + ', fiches F1 à F22 (PARTIE B formateur « porte pédagogique de forcement »)', LIVCE + ', Partie 1, § 1.2 (p. 9) et § 4.1 (p. 26)', 'GTO Établissements et techniques d’extinction (DGSCGC, 2018), ETEX-STR-ETB-1 (p. 55)', 'GTO Engagement en milieu vicié (DGSCGC, 2019), chap. III', 'GDO Incendies de structures (DGSCGC, 2018)', GTOS + ', chap. I § 1.2.6 et chap. III § 3.2.1'],
  summary: 'Le chef tient le Halligan et commande : quand forcer, lire la porte, ordres, sécurité, et les cas que la fiche équipier ne détaille pas (renfort, anti-panique, couloir étroit).',
  why: '<b>Pourquoi est-ce au chef de diriger ?</b> Au forcement, le chef manœuvre le Halligan, voit la zone de travail et donne chaque frappe ; l’équipier, concentré sur la percussion, ne frappe que sur ordre. Mais avant même de frapper, c’est au chef d’équipe de savoir <b>s’il a le droit</b> de forcer, de <b>demander l’outil</b> à son chef d’agrès, de <b>lire la porte</b> et, sur un feu, d’exiger une <b>lance prête</b> : ouvrir une porte, c’est aussi apporter de l’air au feu.',
  sections: [
    { id: 'droit', t: 'Avant de forcer : droit, ordre, moyens', ic: 'shield', src: LIVCE + ', § 1.2 (p. 9) ; ETEX-STR-ETB-1 (p. 55) ; ' + HAL + ', F15',
      html: '<ul class="check"><li><b>La propriété privée est inviolable</b>, protégée par la loi. En cas de <b>péril</b>, le chef d’équipe peut visiter appartements, caves, greniers, ateliers à son initiative ; en cas de refus des occupants, il <b>rend compte</b> immédiatement.</li>' +
        '<li><b>Sans urgence</b>, il demande à son chef d’agrès l’assistance de la police ou de la gendarmerie et <b>attend leur arrivée</b> avant de pénétrer.</li>' +
        '<li>Pour un <b>sauvetage</b> malgré l’opposition des occupants : droit et devoir de pénétrer, <b>de force si nécessaire</b>.</li>' +
        '<li>En reconnaissance, il <b>demande à son chef d’agrès</b> tous les moyens nécessaires, « notamment pour permettre l’ouverture des issues nécessitant une manœuvre de force ».</li></ul>' +
        '<p>Côté matériel, le GTO Établissements propose que l’<b>outil de forcement soit emporté par le chef d’agrès</b> (et non par le BAT) pour l’établissement d’une LDT ; les fiches Halligan citent les <b>OFD</b>, « outils de forcement légers à l’usage des chefs d’agrès ». Chaque SIS fixe la liste des matériels emportés.</p>' +
        '<p class="small muted">La technique de base (outil, rôles, écarter-engager-forcer, porte tirante et poussante, autres outils) est dans le chapitre équipier <a href="#/c/inc-forcement">Le forcement</a>.</p>' },
    { id: 'peda', t: 'Objectifs de la porte pédagogique', ic: 'target', src: HAL + ', F1F',
      html: '<p>Le forcement est un ensemble de techniques pour <b>pénétrer dans des locaux ou des sites dont les accès sont verrouillés, obstrués ou inexistants</b>. À la fin de la séquence, le stagiaire doit être capable de :</p>' +
        '<ol><li>décrire l’outil et ses différentes utilisations ;</li><li>réaliser le forcement d’une porte <b>tirante</b> et d’une porte <b>poussante</b> ;</li><li>respecter <b>rigoureusement</b> les principes de sécurité liés à l’utilisation de l’outil.</li></ol>' },
    { id: 'commander', t: 'Commander le binôme au forcement', ic: 'team', src: HAL + ', F5 et F8F',
      html: '<div class="tw"><table><thead><tr><th>Chef (Halligan)</th><th>Équipier (outil de frappe)</th></tr></thead><tbody>' +
        '<tr><td>Vérifie les EPI : au minimum tenue F1 complète + casque + gants (opérations diverses) ; tenue de feu complète + ARI capelé si nécessaire (incendie).</td><td>S’équipe en conséquence.</td></tr>' +
        '<tr><td>Sur incendie, si la situation le nécessite : fait tenir <b>une LDV en eau prête</b> pour la protection et les contrôles habituels (<b>température de la porte</b>, réaction sur les sorties et couleur des fumées…).</td><td>—</td></tr>' +
        '<tr><td>Se place pour manœuvrer l’outil avec une <b>bonne visibilité de la zone de travail</b> ; sur porte poussante, de préférence <b>côté cadre</b>.</td><td>Debout si la zone de frappe est au niveau ou au-dessus de son plexus, à genoux ou en trépied en dessous ; une main à 15 cm environ sous la tête de l’outil, l’autre en bas du manche.</td></tr>' +
        '<tr><td>Donne des ordres <b>forts et clairs</b> : « <b>FRAPPE</b> » = une frappe ; « <b>STOP</b> » ou main levée pour replacer l’outil ou changer d’étape.</td><td>Entièrement concentré sur la percussion et sur les ordres du chef.</td></tr>' +
        '<tr><td>Stoppe les frappes avant de forcer ; <b>contrôle l’ouverture soudaine</b> d’une porte poussante (poignée tenue à la main, sangle, ou pointeau du Halligan).</td><td>Arrête de frapper au « STOP ».</td></tr>' +
        '</tbody></table></div>',
      figs: [{ img: 'img/ce/3/forcement-ordres.jpg', cap: 'Positionnements et ordres', txt: '<p>À gauche, l’équipier debout ou à genoux selon la hauteur de la zone de frappe ; à droite, « FRAPPE » (une frappe) et « STOP » (frappes interrompues, main levée).</p>', src: HAL + ', F5S' }] },
    { id: 'lire', t: 'Lire la porte avant de frapper', ic: 'eye', src: HAL + ', F3, F4, F8F à F12F',
      html: '<div class="tw"><table><thead><tr><th>Ce que le chef observe</th><th>Conséquence</th></tr></thead><tbody>' +
        '<tr><td><b>Gonds visibles</b> (tirant droit ou tirant gauche)</td><td>Porte <b>tirante</b> : bâtiments publics, industriels, commerciaux, locaux techniques ; en habitation, caves et parkings souterrains.</td></tr>' +
        '<tr><td><b>Pas de gonds visibles</b> (poussant droit ou gauche)</td><td>Porte <b>poussante</b> : portes d’entrée de pavillon ou d’appartement.</td></tr>' +
        '<tr><td>Porte poussante : pousser ou frapper <b>en haut, au milieu, en bas</b></td><td>L’écartement constaté (ou non) indique le <b>nombre et la position des points de verrouillage</b>.</td></tr>' +
        '<tr><td>Plusieurs points de verrouillage</td><td>Répéter les 3 phases pour chacun ; s’ils sont à <b>50 cm maximum</b> environ, travailler entre les deux.</td></tr>' +
        '<tr><td>Verrou</td><td>Pointeau sur la partie creuse de la serrure, une frappe sur ordre, éjection du verrou par l’intérieur.</td></tr>' +
        '<tr><td>Porte <b>encastrée ou en retrait</b></td><td>L’herminette doit être guidée dans l’arrêt de porte et avoir l’espace pour s’écarter : on peut faire un <b>trou dans le mur</b> pour manœuvrer l’outil.</td></tr>' +
        '<tr><td>Porte dans un <b>couloir étroit</b></td><td>Faire glisser la tête de la hache le long du Halligan et frapper sur l’<b>épaulement de la fourche</b> (qui doit être bien carré) ; mettre le biseau sur le cadre facilite l’entrée et donne un meilleur angle de frappe.</td></tr>' +
        '</tbody></table></div>',
      figs: [{ img: 'img/ce/3/poussante-phases.jpg', cap: 'Porte poussante : écarter, engager, forcer', txt: '<p>L’herminette écarte la porte du cadre, la fourche s’engage entre porte et butoir sous les frappes en redressant l’outil à 90°, puis le levier s’exerce vers la porte.</p>', src: HAL + ', F8F' }] },
    { id: 'renfort', t: 'Porte avec renfort (cornière)', ic: 'grid', src: HAL + ', F13F',
      html: '<p>Le renfort est en général <b>boulonné à la porte</b>, partiel ou sur toute la longueur ; la cornière peut être en fer plat ou blindée.</p>',
      steps: ['Placer la fourche entre le renfort et le cadre, Halligan perpendiculaire à la porte.', 'Verrouiller le bout de la fourche dans le butoir et pousser fermement : ÉCARTER la porte avec la fourche.', 'Repositionner l’outil et le guider : ENGAGER.', 'Utiliser la cornière comme appui : FORCER.', 'Variante (système vissé dans le cadre) : guider l’extrémité de la fourche entre renfort et cadre jusqu’à toucher la porte, pousser vers la porte pour faire sauter ou tordre le renfort, puis engager et forcer.', 'Renfort sur une porte qui s’ouvre vers l’extérieur : guider l’herminette entre porte et renfort et plier largement le renfort pour laisser entrer le Halligan ; couper les boulons, faire levier, plier ou enlever le renfort en dernier ressort.'], stepsTitle: 'Technique sur renfort (6)',
      after: '<div class="callout ok"><b>Conseil technique</b> (fiche F13) : parfois, si le renfort est bien protégé, il peut aider à ouvrir la porte ; sinon il faudra l’enlever pour accéder à la porte.</div>',
      figs: [{ img: 'img/ce/3/renfort-corniere.jpg', cap: 'Renfort sur le bord d’une porte', txt: '<p>Herminette ou fourche glissée sous la bande métallique, puis manœuvrée entre la porte et le cadre (inverser l’outil si nécessaire).</p>', src: HAL + ', F13F' }] },
    { id: 'antipanique', t: 'Ouvrir de l’extérieur une porte anti-panique', ic: 'walk', src: HAL + ', F14F',
      steps: ['ÉCARTER : réaliser une ouverture en frappant avec la hache, le pointeau au milieu de la porte.', 'Continuer à agrandir avec l’herminette.', 'ENGAGER : faire pénétrer la fourche en frappant avec la hache.', 'FORCER : relever le Halligan pour venir appuyer sur la barre anti-panique et ouvrir.'], stepsTitle: 'Porte anti-panique (4)',
      figs: [{ img: 'img/ce/3/anti-panique.jpg', cap: 'Ouvrir de l’extérieur une porte anti-panique', txt: '<p>On ne force pas la serrure : on perce la porte pour atteindre la barre anti-panique et l’actionner avec le Halligan.</p>', src: HAL + ', F14F' }] },
    { id: 'usages', t: 'Le Halligan, outil du chef en reconnaissance et en sauvetage', ic: 'bulb', src: LIVCE + ', § 4.1 (p. 26) ; ' + HAL + ', F17, F20, F22 ; GTO Engagement en milieu vicié 2019, chap. III ; GDO Incendies de structures ; ' + GTOS + ', p. 29, 73 et 122',
      html: '<ul class="check"><li><b>Reconnaissance</b> : le livret CE conseille d’utiliser le <b>manche de la hache à tête plate</b> pour atteindre les endroits difficiles d’accès. Fiche F20 : Halligan pointeau et herminette au sol en agitant la fourche, ou hache tenue par la tête plate en agitant le manche, pour fouiller sous un lit ou un meuble et faire vite le tour d’une pièce.</li>' +
        '<li><b>Itinéraire de secours</b> : fracturer des ouvrants, créer des brèches dans des cloisons minces (F20) ; le GDO cite l’outil de forcement pour créer un itinéraire de secours, et le GTO vicié la brèche dans une cloison pour évacuer en urgence.</li>' +
        '<li><b>Binôme de sécurité</b> : il peut constituer un parc matériel incluant des outils de forcement (GTO vicié).</li>' +
        '<li><b>Ancrage et extraction</b> : l’outil de forcement est un ancrage « artificiel » (GTO Sauvetage) ; un Halligan avec une sangle multifonction peut servir à l’amarrage ou au blocage d’une échelle à mains ; son manche engagé dans les bretelles du dossard permet d’extraire un sauveteur.</li>' +
        '<li><b>Marchepied</b> : pointer le sol au pointeau pour éviter le glissement ; astuce : une commande fixée au Halligan permet de le récupérer une fois l’obstacle franchi (F17).</li>' +
        '<li><b>Feu de VL</b> : pointer à l’angle avant du capot ou au-dessus des passages de roue, soulever la tôle en faisant levier, insérer la LDV (F22).</li></ul>' +
        '<div class="callout warn">Le GDO met en garde : alourdir la dotation peut produire l’effet inverse (fatigue, mise en difficulté) ; une solution peut être d’associer un agent au binôme pour travailler en trinôme.</div>' }
  ],
  key: ['Propriété inviolable : péril → visite à son initiative ; refus → compte rendu ; sans urgence → police/gendarmerie via le chef d’agrès.', 'Sauvetage : droit et devoir de pénétrer, de force si nécessaire.', 'Le chef demande les moyens de forcement à son chef d’agrès (outil proposé dans la dotation du chef d’agrès, OFD).', 'Chef = Halligan, visibilité de la zone, ordres forts et clairs ; FRAPPE = une frappe ; STOP ou main levée.', 'Sur incendie : LDV en eau prête si nécessaire, température de la porte, fumées.', 'Gonds visibles = tirante ; pas de gonds = poussante ; tester en haut, au milieu, en bas.', 'Couloir étroit : frapper sur l’épaulement de la fourche.', 'Anti-panique : percer, agrandir, engager la fourche, appuyer sur la barre.'],
  traps: ['Forcer une porte sans urgence ni présence des forces de l’ordre.', 'Ouvrir une porte de local en feu sans lance prête ni contrôle de la température.', 'Commencer à frapper sans avoir testé les points de verrouillage d’une porte poussante.', 'Laisser une porte poussante s’ouvrir brutalement : la contrôler (main, sangle, pointeau).', 'S’acharner sur la serrure d’une porte anti-panique au lieu d’atteindre la barre.'],
  quiz: [
    { q: 'En reconnaissance sans urgence, les occupants refusent l’accès. Le chef d’équipe :', c: ['Demande au chef d’agrès l’assistance de la police ou de la gendarmerie et attend leur arrivée', 'Force la porte immédiatement', 'Abandonne sans rendre compte', 'Demande à son équipier de forcer pendant qu’il parlemente'], e: 'Livret CE § 1.2 « RECONNAISSANCE » : sans urgence, assistance de la police ou de la gendarmerie et attente avant de pénétrer.', s: 'droit' },
    { q: 'Selon le GTO Établissements (fiche LDT), qui emporte l’outil de forcement ?', c: ['Le chef d’agrès', 'Le chef du BAT', 'L’équipier du BAT', 'Le conducteur'], e: 'ETEX-STR-ETB-1, p. 55 : dans le tableau des matériels proposés, l’outil de forcement figure dans la ligne du chef d’agrès. Chaque SIS précise sa liste.', s: 'droit' },
    { q: 'Sur un incendie, que doit exiger le chef avant de forcer un ouvrant, si la situation le nécessite ?', c: ['Une LDV en eau prête pour la protection et les contrôles (température de porte, fumées)', 'Une ventilation en surpression', 'L’arrivée de la police', 'Le retrait des ARI pour plus de mobilité'], e: 'Fiche F5F : une LDV en eau doit pouvoir être prête à assurer la protection du personnel et les contrôles habituels.', s: 'commander' },
    { q: 'Où se place de préférence le chef sur une porte poussante ?', c: ['Côté cadre, pour bien voir la zone de travail', 'Derrière l’équipier', 'Côté gonds', 'À genoux sous l’équipier'], e: 'Fiche F8F : le chef se positionne de préférence côté cadre pour avoir une bonne visibilité de la zone de travail.', s: 'commander' },
    { q: 'Comment déterminer les points de verrouillage d’une porte poussante ?', c: ['Pousser ou frapper en haut, au milieu et en bas, et observer l’écartement', 'Regarder les gonds', 'Compter les serrures visibles uniquement', 'Frapper au centre jusqu’à ouverture'], e: 'Fiche F8F « TESTER ».', s: 'lire' },
    { q: 'Dans un couloir étroit où la hache se manie mal :', c: ['Faire glisser la tête de la hache le long du Halligan et frapper sur l’épaulement de la fourche', 'Renoncer au forcement', 'Frapper avec le Halligan sur la hache', 'Utiliser la disqueuse obligatoirement'], e: 'Fiche F11F : autre méthode de frappe, l’épaulement de la fourche doit être bien carré.', s: 'lire' },
    { q: 'Sur une porte avec cornière de renfort, on utilise la cornière :', c: ['Comme appui pour forcer', 'Comme zone de frappe', 'Jamais : on l’arrache toujours en premier', 'Comme point d’ancrage du LSPCC'], e: 'Fiche F13F : repositionner l’outil, engager, puis utiliser la cornière comme appui pour forcer ; l’enlever seulement en dernier ressort.', s: 'renfort' },
    { q: 'Pour ouvrir de l’extérieur une porte anti-panique, la phase « forcer » consiste à :', c: ['Relever le Halligan pour appuyer sur la barre anti-panique', 'Faire céder la serrure par levier', 'Dégonder la porte', 'Découper la barre'], e: 'Fiche F14F : ouverture au pointeau, agrandissement à l’herminette, fourche engagée, puis Halligan relevé pour appuyer sur la barre.', s: 'antipanique' }
  ]
});
